import{c as a,Q as _,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"__asc_cvt_float2_to_fp8x2","description":"","frontmatter":{},"headers":[{"level":1,"title":"\\\\_\\\\_asc\\\\_cvt\\\\_float2\\\\_to\\\\_fp8x2","slug":"__asc_cvt_float2_to_fp8x2"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMT-API/数学函数/fp8类型/fp8数据转换函数/__asc_cvt_float2_to_fp8x2.md","filePath":"api/SIMT-API/数学函数/fp8类型/fp8数据转换函数/__asc_cvt_float2_to_fp8x2.md"}'),l={name:"api/SIMT-API/数学函数/fp8类型/fp8数据转换函数/__asc_cvt_float2_to_fp8x2.md"};function n(p,t,i,o,d,r){return _(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="asc-cvt-float2-to-fp8x2" tabindex="-1">__asc_cvt_float2_to_fp8x2 <a class="header-anchor" href="#asc-cvt-float2-to-fp8x2" aria-label="Permalink to &quot;\\_\\_asc\\_cvt\\_float2\\_to\\_fp8x2&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将float2类型数据的两个分量，按照CAST_RINT模式转换为指定类型（float8_e4m3x2_t和float8_e5m2x2_t）的8位浮点数，并根据指定的饱和模式（饱和或非饱和）进行溢出处理。转换结果以位级打包形式存储为__asc_fp8x2_storage_t类型，该类型为16位无符号整数unsigned short int，用于存储float8_e4m3x2_t或float8_e5m2x2_t类型的数据。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__asc_fp8x2_storage_t __asc_cvt_float2_to_fp8x2(const float2 x, const __asc_saturation_t saturate, const __asc_fp8_interpretation_t fp8_interpretation)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>x</td><td>输入</td><td>源操作数。</td></tr><tr><td>saturate</td><td>输入</td><td>控制饱和行为，支持的取值为：__ASC_NOSAT、__ASC_SATFINITE。 __ASC_NOSAT表示使用非饱和模式，__ASC_SATFINITE表示使用饱和模式。</td></tr><tr><td>fp8_interpretation</td><td>输入</td><td>指定转换类型，支持的取值为：__ASC_E4M3、__ASC_E5M2。 __ASC_E4M3表示转换为float8_e4m3x2_t格式的浮点数，__ASC_E5M2表示转换为float8_e5m2x2_t格式的浮点数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>输入的两个分量遵循CAST_RINT模式，根据指定的8位浮点数类型和指定的饱和模式，转换成的__asc_fp8x2_storage_t类型数据。</p><ul><li>float8_e4m3_t数据类型没有inf值，非饱和模式下输入超出该类型所能表示的范围时，其溢出结果为nan，饱和模式下溢出结果为该类型表示的最大值或最小值。</li><li>float8_e5m2_t类型则有inf值，非饱和模式下输入超出该类型所能表示的范围，转换结果为对应符号的inf值，饱和模式下溢出结果为该类型表示的最大值或最小值。</li><li>饱和模式下，对于float8_e5m2_t和float8_e4m3_t数据类型，当寄存器CTRL[50]=0时，nan值会被转换为0，当寄存器CTRL[50]=1时，nan值被转化为fp8类型下的nan值。CTRL寄存器值可通过<a href="./../../../../SIMD-API/基础API/系统变量访问/GetCtrlSpr(ISASI).html">GetCtrlSpr(ISASI)</a>接口获取。</li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>使用此接口前需将CTRL[60]寄存器设置为0，否则饱和行为控制不生效。设置方式请参见<a href="./../../数据类型转换/概述-258.html#section1194916101549">控制饱和行为的方式</a>。</p><p>SIMT编程场景当前不支持使用该接口。</p><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><p>使用该接口需要包含&quot;simt_api/asc_fp8.h&quot;头文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;simt_api/asc_fp8.h&quot;</span></span></code></pre></div><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>SIMD与SIMT混合编程场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 使用短向量可提升数据搬运效率</span></span>
<span class="line"><span>__simt_vf__ __launch_bounds__(1024) inline void simt_asc_cvt_float2_to_fp8x2(__gm__ float2* input, __gm__ uint16_t* output, uint32_t input_total_length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;</span></span>
<span class="line"><span>    // 每个线程处理1个float2类型的数据，即2个float类型的数据，因此idx &gt;= input_total_length / 2的线程不处理数据</span></span>
<span class="line"><span>    if (idx &gt;= input_total_length / 2) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    output[idx] = __asc_cvt_float2_to_fp8x2(input[idx], __ASC_NOSAT, __ASC_E4M3);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>__global__ __vector__ void cast_kernel(__gm__ float* input, __gm__ uint16_t* output, uint32_t input_total_length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    asc_vf_call&lt;simt_asc_cvt_float2_to_fp8x2&gt;(dim3(1024), (__gm__ float2*)input, output, input_total_length);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ul>`,21)])])}const f=a(l,[["render",n]]);export{h as __pageData,f as default};
